61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger; a successful create emits one line here. */
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
70	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
114	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        String address = normalizeAddress(owner.getAddress());
123	        if (address.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        owner.setAddress(address);
127	        if (owner.getEmail() != null) {
128	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        String telephone = normalizeTelephone(owner.getTelephone());
135	        if (telephone == null) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setTelephone(telephone);
139	        LocalDate registrationDate = resolveRegistrationDate(owner.getRegistrationDate());
140	        owner.setRegistrationDate(registrationDate);
141	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        if (isTelephoneInUse(telephone)) {
145	            return new ResponseEntity<>(HttpStatus.CONFLICT);
146	        }
147	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        if (countOwnersInCity(owner.getCity()) >= 50) {
151	            return new ResponseEntity<>(HttpStatus.CONFLICT);
152	        }
153	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
154	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), registrationDate));
155	        owner.setHouseholdId(householdId(owner));
156	        owner.setNamesakeCount(countNamesakes(owner));
157	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
158	        this.clinicService.saveOwner(owner);
159	        AUDIT.info("Owner created id={} customerCode={} registrationDate={}",
160	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
171	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
172	        if (currentOwner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        currentOwner.setAddress(ownerFieldsDto.getAddress());
176	        currentOwner.setCity(ownerFieldsDto.getCity());
177	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
178	        currentOwner.setLastName(ownerFieldsDto.getLastName());
179	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
180	        String email = ownerFieldsDto.getEmail();
181	        if (email != null) {
182	            email = email.trim().toLowerCase(Locale.ROOT);
183	            if (!EMAIL_PATTERN.matcher(email).matches()) {
184	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	            }
186	        }
187	        currentOwner.setEmail(email);
188	        this.clinicService.saveOwner(currentOwner);
189	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Transactional
194	    @Override
195	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
196	        Owner owner = this.clinicService.findOwnerById(ownerId);
197	        if (owner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        this.clinicService.deleteOwner(owner);
201	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        HttpHeaders headers = new HttpHeaders();
212	        Pet pet = petMapper.toPet(petFieldsDto);
213	        owner.setId(ownerId);
214	        pet.setOwner(owner);
215	        pet.getType().setName(null);
216	        this.clinicService.savePet(pet);
217	        PetDto petDto = petMapper.toPetDto(pet);
218	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
219	            .buildAndExpand(pet.getId()).toUri());
220	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
221	    }
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
226	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
227	        if (currentOwner != null) {
228	            Pet currentPet = this.clinicService.findPetById(petId);
229	            if (currentPet != null) {
230	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
231	                currentPet.setName(petFieldsDto.getName());
232	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
233	                this.clinicService.savePet(currentPet);
234	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
235	            }
236	        }
237	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
243	        HttpHeaders headers = new HttpHeaders();
244	        Visit visit = visitMapper.toVisit(visitFieldsDto);
245	        Pet pet = new Pet();
246	        pet.setId(petId);
247	        visit.setPet(pet);
248	        this.clinicService.saveVisit(visit);
249	        VisitDto visitDto = visitMapper.toVisitDto(visit);
250	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
251	            .buildAndExpand(visit.getId()).toUri());
252	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
253	    }
254	
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner != null) {
261	            Pet pet = owner.getPet(petId);
262	            if (pet != null) {
263	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
264	            }
265	        }
266	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
267	    }
268	
269	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
270	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
271	
272	    /**
273	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
274	     * code are kept when present; otherwise country code '+61' is assumed and a single
275	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
276	     * stripped. The result must be a '+' followed by 8 to 15 digits.
277	     * Returns {@code null} when the number cannot form a valid E.164 value.
278	     */
279	    private static String normalizeTelephone(String telephone) {
280	        if (telephone == null) {
281	            return null;
282	        }
283	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
284	        String e164;
285	        if (cleaned.startsWith("+")) {
286	            e164 = cleaned;
287	        } else {
288	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
289	            e164 = "+61" + national;
290	        }
291	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
292	    }
293	
294	    /**
295	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
296	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
297	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
298	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
299	     */
300	    private String generateCustomerCode(String city, String lastName) {
301	        String city3 = firstThreeLetters(city);
302	        String last3 = firstThreeLetters(lastName);
303	        int sequence = countOwnersInCity(city) + 1;
304	        return String.format("%s-%s-%04d", city3, last3, sequence);
305	    }
306	
307	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
308	    private static String firstThreeLetters(String value) {
309	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
310	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
311	    }
312	
313	    /**
314	     * The number of existing owners registered in {@code city}, compared case-insensitively
315	     * with collapsed whitespace.
316	     */
317	    private int countOwnersInCity(String city) {
318	        String normalized = normalizeHouseholdField(city);
319	        return (int) this.clinicService.findAllOwners().stream()
320	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
321	            .count();
322	    }
323	
324	    /**
325	     * The effective registration date to store for a new owner: the date supplied on the request
326	     * when present, otherwise the current server date, in either case rolled forward to a business
327	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
328	     * This single point of resolution is what every registration-date-derived value (the stored
329	     * date, the membership number's year segment, the per-day create-limit) is computed from.
330	     */
331	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
332	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
333	        return toBusinessDay(date);
334	    }
335	
336	    /**
337	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
338	     * following Monday; a weekday is returned unchanged.
339	     */
340	    private static LocalDate toBusinessDay(LocalDate date) {
341	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
342	            date = date.plusDays(1);
343	        }
344	        return date;
345	    }
346	
347	    /**
348	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
349	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
350	     */
351	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
352	        String yy = String.format("%02d", registrationDate.getYear() % 100);
353	        return customerCode + "-M" + yy;
354	    }
355	
356	    /**
357	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
358	     * last name, compared case-insensitively.
359	     */
360	    private int countNamesakes(Owner owner) {
361	        String firstName = normalizeHouseholdField(owner.getFirstName());
362	        String lastName = normalizeHouseholdField(owner.getLastName());
363	        return (int) this.clinicService.findAllOwners().stream()
364	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
365	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
366	            .count();
367	    }
368	
369	    /**
370	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
371	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
372	     * unusually high daily signup volume.
373	     */
374	    private boolean isBulkSignupWarning() {
375	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
376	    }
377	
378	    /** The number of existing owners whose registration date is {@code date}. */
379	    private int countOwnersRegisteredOn(LocalDate date) {
380	        return (int) this.clinicService.findAllOwners().stream()
381	            .filter(existing -> date.equals(existing.getRegistrationDate()))
382	            .count();
383	    }
384	
385	    /** Whether any existing owner already uses the given (E.164) telephone number. */
386	    private boolean isTelephoneInUse(String telephone) {
387	        return this.clinicService.findAllOwners().stream()
388	            .map(Owner::getTelephone)
389	            .filter(existing -> existing != null)
390	            .map(OwnerRestControllerV1::normalizeTelephone)
391	            .filter(existing -> existing != null)
392	            .anyMatch(telephone::equals);
393	    }
394	
395	    /** Common street-type abbreviations expanded during address normalization. */
396	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
397	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
398	
399	    /**
400	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
401	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
402	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
403	     * string when {@code address} is null or blank after normalization.
404	     */
405	    private static String normalizeAddress(String address) {
406	        if (address == null) {
407	            return "";
408	        }
409	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
410	        if (collapsed.isEmpty()) {
411	            return "";
412	        }
413	        StringBuilder sb = new StringBuilder(collapsed.length());
414	        for (String token : collapsed.split(" ")) {
415	            if (sb.length() > 0) {
416	                sb.append(' ');
417	            }
418	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
419	        }
420	        return sb.toString();
421	    }
422	
423	    /**
424	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
425	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
426	     */
427	    private static String normalizeHouseholdField(String value) {
428	        if (value == null) {
429	            return "";
430	        }
431	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
432	    }
433	
434	    /**
435	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
436	     * same address compared case-insensitively with collapsed whitespace.
437	     */
438	    private List<Owner> findHousemates(Owner owner) {
439	        String lastName = normalizeHouseholdField(owner.getLastName());
440	        String address = normalizeHouseholdField(owner.getAddress());
441	        return this.clinicService.findAllOwners().stream()
442	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
443	                && normalizeHouseholdField(existing.getAddress()).equals(address))
444	            .toList();
445	    }
446	
447	    /**
448	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
449	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
450	     */
451	    private boolean isHouseholdInUse(Owner owner) {
452	        return !findHousemates(owner).isEmpty();
453	    }
454	
455	    /**
456	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
457	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself. A value of
458	     * 3 or more raises the membership tier to GOLD.
459	     */
460	    private int countHouseholdMembers(Owner owner) {
461	        return findHousemates(owner).size() + 1;
462	    }
463	
464	    /**
465	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
466	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
467	     * deterministically from those normalized fields so housemates always resolve to the same value,
468	     * regardless of registration order.
469	     */
470	    private static String householdId(Owner owner) {
471	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
472	            + normalizeHouseholdField(owner.getAddress());
473	        try {
474	            byte[] digest = MessageDigest.getInstance("SHA-256")
475	                .digest(key.getBytes(StandardCharsets.UTF_8));
476	            StringBuilder sb = new StringBuilder(24);
477	            for (int i = 0; i < 12; i++) {
478	                sb.append(String.format("%02X", digest[i]));
479	            }
480	            return sb.toString();
481	        }
482	        catch (NoSuchAlgorithmException e) {
483	            throw new IllegalStateException("SHA-256 not available", e);
484	        }
485	    }
486	}
